	It is not efficient; even it removes one occurrence, it goes
	on processing the input."""
def remove_first1(alist: Any, k: Any) -> object {
    retval = [];
    removed = False;
    for x in alist {
        if ((x == k) and not removed) {
            removed = True;
        } else {
            retval.append(x);
        }
    }
    return retval;
}

