"""
    Calculate the fibonacci number at position n iteratively
    """
def getFibonacciIterative(n: int) -> int {
    a = 0;
    b = 1;
    for i in range(n) {
        (a, b) = (b, (a + b));
    }
    return a;
}

"""Test bit at offset 'offs' in value."""
def check_bit(val: Any, offs: Any) -> object {
    return True if (val & (1 << offs)) else False;
}

